    [%desc_a],              // SMEM descriptor for A operand
    [%desc_b],              // SMEM descriptor for B operand
    %scale_d,               // Scale descriptor for D (output)
    %enable_mask,
    [%scale_a_smem],        // UE8M0 scales for A in SMEM
    [%scale_b_smem];        // UE8M0 scales for B in SMEM
